footer._p.append(field)

def p(text, style=None):
    return doc.add_paragraph(text, style)

def h(text, level=1):
    doc.add_heading(text, level)

def bullets(items):
    for item in items:
        p(item, 'List Bullet')

def table(headers, rows):
    t = doc.add_table(rows=1, cols=len(headers))
    t.style = 'Light Shading Accent 1'
    for c, text in zip(t.rows[0].cells, headers):
        c.text = text
    repeat = OxmlElement('w:tblHeader')
    t.rows[0]._tr.get_or_add_trPr().append(repeat)
    for row in rows:
        cells = t.add_row().cells
        for c, text in zip(cells, row):
            c.text = text
            for para in c.paragraphs:
                para.paragraph_format.space_after = Pt(4)
                for r in para.runs:
                    r.font.size = Pt(10)
    p('')

def link(label, url):
    para = doc.add_paragraph()
    para.add_run(label + ' ')
    rel = para.part.relate_to(url, 'http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink', is_external=True)
    node = OxmlElement('w:hyperlink')
    node.set(qn('r:id'), rel)
    run = OxmlElement('w:r')
    props = OxmlElement('w:rPr')
    color = OxmlElement('w:color'); color.set(qn('w:val'), '0563C1'); props.append(color)
    run.append(props)
    text = OxmlElement('w:t'); text.text = url; run.append(text)
    node.append(run); para._p.append(node)

