steps = [('Збереження оригіналів', 'Зберігати файл, URL, дату отримання, версію та контрольну суму; не перезаписувати сирі дані очищеною версією.'), ('Узгодження структури', 'Привести назви полів, формати дат, числові типи та одиниці вимірювання до спільного формату. Для збитків зберігати валюту, масштаб одиниць і відомості про коригування на інфляцію.'), ('Узгодження категорій', 'Створити таблицю відповідності класифікацій EM-DAT і ДСНС. Неоднозначні відповідності явно позначати.'), ('Перевірка територій', 'Не переносити автоматично всі події СРСР до України; використовувати підтверджену географію. Фіксувати версію територіального поділу.'), ('Виявлення дублікатів', 'Зіставляти дати, території, типи й джерела; зберігати походження об’єднаних записів та журнал неоднозначних випадків.'), ('Обробка пропусків', 'Невідомі збитки чи кількість загиблих не замінювати нулями. Не вигадувати день і місяць, якщо відомий лише рік.'), ('Перевірка аномалій', 'Перевіряти підозрілі значення за джерелами. Великі катастрофи можуть бути справжніми крайніми спостереженнями, а не помилками.'), ('Побудова часових рядів', 'Відрізняти підтверджений нуль від відсутності звітності. Агрегувати лише до рівня, який підтримують джерела.'), ('Підготовка ознак', 'Навчати масштабування та заповнення пропусків лише на тренувальних даних. Для прогнозу використовувати тільки інформацію, доступну на момент розрахунку.'), ('Звіт якості', 'Показати покриття років і територій, частки пропусків, дублікати, неоднозначності та кількість записів до і після обробки.')]
